entries[1305972] = { ["name"] = "Oozing Goby", ["text"] = "5 yd range\n3.2 sec cast\nDescription:\nGiving the goby a gentle squeeze causes a gush of viscous poison to crawl from its too-many eyes. If you must handle this fish, do so with gloves.\n\nAreas you can find this fish:\n- The Coiled Isle" }
entries[1305973] = { ["name"] = "Giggling Skull", ["text"] = "5 yd range\n3.2 sec cast\nDescription:\nNobody is sure where this \"fish\" came from, or how to get rid of it. It's named for the unsettling sound it makes while darting through the water that haunts all who hear it.\n\nAreas you can find this fish:\n- The Coiled Isle" }
entries[1305974] = { ["name"] = "Spark of Tides", ["text"] = "Instant\nCompleting this quest can reward you with a weekly Spark of Tides. These sparks are usable by professions to create powerful weapons and armor.\n\nIf you fall behind on these weekly sparks, completing other max-level content such as Delves, Mythic Plus, Raids, Instanced PvP, and some outdoor events may help you catch up.\n\nYou have already received your Spark of Tides this week." }
entries[1305975] = { ["name"] = "Grotesque Sturgeon", ["text"] = "5 yd range\n3.2 sec cast\nDescription:\nSturgeon populations have been steadily declining, alarming local ecologists. They were even further alarmed when they discovered the sturgeons were growing legs and simply wandering away.\n\nAreas you can find this fish:\n- The Coiled Isle" }
entries[1305976] = { ["name"] = "Many-Eyed Flounder", ["text"] = "5 yd range\n3.2 sec cast\nDescription:\nDo not look into its eyes. This is difficult because this flounder is almost entirely eyes.\n\nAreas you can find this fish:\n- The Coiled Isle" }
entries[1305977] = { ["name"] = "Nebulous Voidcores", ["text"] = "Instant\nGrants access to additional Nebulous Voidcores in Midnight Season 2, used to obtain powerful items from raid bosses, Mythic+ dungeons, Bountiful delves, and Nightmare Prey." }
entries[1305978] = { ["name"] = "Twin-Headed Snipefish", ["text"] = "5 yd range\n3.2 sec cast\nDescription:\nThe Twin-Headed Snipefish is a rare fish and has yet to be studied in depth. It's not clear whether this is a new species or a peculiar mutation, but at least one thing is for sure: one head is for aiming and one is for firing.\n\nAreas you can find this fish:\n- The Coiled Isle" }
entries[1305979] = { ["name"] = "Loathsome Anglerfish", ["text"] = "5 yd range\n3.2 sec cast\nDescription:\n\"Revolting\" is the first word that comes to mind upon seeing this creature. It has as many teeth as there are stars in the sky. And yet, the light it emits is comforting, compelling. It beckons...\n\nWhatever you do, do not follow the lights.\n\nAreas you can find this fish:\n- The Coiled Isle" }
